/// <summary>
/// MPJ-3746 - KScerri - 07/05/2021
/// The <c>METPayTermTable_Extension</c> class extension required to add additional logic to payment due date calculation
/// </summary>
[ExtensionOf(tableStr(PaymTerm))]
public final class METPayTermTable_Extension
{
}

Method.Source:
    /// <summary>
    /// MPJ-3746 - KScerri - 07/05/2021
    /// Extending adjustDueDateBeforeRoundOffDueDate to modify the cutoff date
    /// </summary>
    /// <param name = "_transDate">Trans date</param>
    /// <param name = "_dueDate">Due date</param>
    /// <param name = "_paymDayId">payment day ID</param>
    /// <returns>DueDate</returns>
    protected DueDate adjustDueDateBeforeRoundOffDueDate(TransDate _transDate, DueDate _dueDate, PaymDayId _paymDayId)
    {
        int dayOfDate;
        var dueDate = next adjustDueDateBeforeRoundOffDueDate(_transDate, _dueDate, _paymDayId);

        dayOfDate = dayofmth(_transDate);

        if (this.METCutOffDays > 0 && this.METCutOffDays < dayOfDate)
        {
            dueDate = nextMth(dueDate);
        }

        return dueDate;
    }
